	RITUAL_SHARE_FAILED = "Impossibile creare i tip delle challenge.",

	-- Weekly hint (perché la weekly Ritual non è ancora fatta)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Bloccata: %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Bloccata — sblocca i Ritual Site tramite la questline introduttiva a Silvermoon.",
	RITUAL_WEEKLY_HINT_PICKUP = "Non ancora presa — questa weekly arriva da Lady Liadrin a Silvermoon, e solo nelle settimane in cui la offre come una delle sue quattro scelte.",
	RITUAL_WEEKLY_HINT_INTRO = "Questo personaggio non ha ancora finito la questline introduttiva — inizia \"Ranger Captain's Summons\" da Ranger Captain Lilatha a Silvermoon (lo step Void Strike avviene nella zona di assalto attiva).",
	RITUAL_INTRO_STEP_FMT = "Questline introduttiva su questo personaggio — step %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(già nel tuo registro delle quest)",
	RITUAL_INTRO_STEP_SUMMONS = "inizia \"Ranger Captain's Summons\" da Ranger Captain Lilatha, allo staging ground sopra il Bazaar.",
	RITUAL_INTRO_STEP_ALLIES = "fai \"Outfitting and Allies\" — incontra gli alleati allo staging ground di Lilatha.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — questo step si svolge nella zona di assalto attiva (vedi Void Assault più sotto).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — indaga sui report dei Ritual Site, poi sabota un Ritual Site.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — fai rapporto a Lady Darkglen all'hub.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "È nel tuo registro delle quest — finiscila e consegnala.",

	-- Intro / come funziona --------------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Scegli il tuo tier alla Curious Obelisk; completa ogni tier per sbloccare il successivo.|n• L'obelisco dice cosa chiede ogni tier: il Tier 3 richiede 1 challenge attiva, il Tier 4 ne richiede 2, il Tier 5 ne richiede 4, il Tier 6 ne richiede 6.|n• I tier più alti danno più Spoils e renown. Item level consigliato dal gioco, letto dall'obelisco stesso il 20 agosto: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Passa il mouse su un tier nel menu per verificarlo tu stesso — questi numeri cambiano da una stagione all'altra.",
	RITUAL_TIP_INTRO_SCORING = "• Gli Spoils sono il tuo punteggio; il Ritual Chest finale scala con essi.|n• Morti: le prime 2 sono gratis, poi ogni morte taglia gli Spoils del 5%, fino a un massimo del -50%.|n• Le run pulite battono i pull veloci — morire costa ricompense in modo diretto.",
	RITUAL_TIP_INTRO_WEEKLY = "• Al lancio, il tier necessario per SBLOCCARE una challenge calava di uno ogni settimana. Va avanti da mesi, quindi ormai molto probabilmente basta un tier basso.|n• Conta per la riga World della Great Vault, come un Delve dello stesso tier.|n• Booster del renown: Ritual Tablet (primo sito della settimana), Ritual Tablet Fragment (secondo sito) e Ritual Site Reports (scalati in base ai tuoi Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• In combat, i Regeneration Orb si manifestano e curano il 15% della tua vita (Renown 1).|n• Orb Potency (Renown 4) aumenta quella cura.|n• Affidati agli orb invece di bruciare cooldown sul self-healing.",

	-- Daggerspine Point (Eversong Woods) -------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, sulla costa ovest vicino a Goldenmist Village.|n• Nemici: naga.|n• Attivo una settimana per volta; l'obelisco mostra un'icona viola sulla mappa.|n• Entra alla Curious Obelisk e scegli lì il tuo tier + le challenge.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Un breve scenario istanziato in tre fasi: uccidi gli elite con nome intorno al sito, poi il Void-Infused Mindbreaker, poi Lady Selen'vjar in persona.|n• Scenario visto all'obelisco: “A Strike From the Sea”.|n• Dopo il kill, saccheggia il Ritual Chest di Lady Selen'vjar, poi esci dall'Obelisk Portal dietro l'edificio.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (sblocca la challenge Tainted Corpses): /way 66.09 62.58.|n• Dark Obelisk (quest Malevolent Boons — esamina 5 qualsiasi; 9 spawn): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• Piccoli tesori e Regeneration Orb sono sparsi per il sito.",

	-- Broken Throne (Zul'Aman) -----------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, nel sud della zona.|n• Nemici: cultisti di Twilight's Blade.|n• Attivo una settimana per volta; l'obelisco mostra un'icona viola sulla mappa.|n• Entra alla Curious Obelisk e scegli lì il tuo tier + le challenge.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Un breve scenario istanziato in tre fasi: uccidi i nemici con nome intorno al sito, poi il Corrupted Amani Dragonhawk, poi Faithbreaker Ger'lok dentro l'edificio.|n• Scenario visto all'obelisco: “A Corrupted Path”.|n• Corrupted Amani Dragonhawk: mettiti nelle piccole pozze rosse (Volatile Plumage) così non esplodono su tutto il gruppo, e non stare mai davanti al suo Shadowflame Breath.|n• Solo con la challenge Malevolent Boons: i Dark Obelisk danno ai nemici incantesimi extra, come una Binding Nebula che ti intrappola finché non la uccidi, e specchi void di cui devi interrompere il cast. Distruggi prima gli obelisk e non arriva niente di tutto questo.|n• Poi saccheggia il Ritual Chest di Faithbreaker Ger'lok.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (sblocca la challenge Tainted Corpses): /way 47.91 36.52.|n• Dark Obelisk (quest Malevolent Boons — esamina 5 qualsiasi; 9 spawn): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54 · 50/57 · 45/64 · 47/76.|n• Distruggere i Dark Obelisk rimuove i buff che potenziano i nemici del sito — eliminarli rende i boss decisamente più facili (lasciali in piedi solo se punti all'achievement no-obelisk).|n• Piccoli tesori e Regeneration Orb sono sparsi per il sito.",
	-- Ritual Boss Coach (finestra boss; EditBox -> {SPELL:} qui è permesso).
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291559} lascia piccole POZZE ROSSE. Mettiti in una per soakarla: subisci solo un colpetto. Una pozza dove non sta nessuno esplode con danni Shadowflame enormi e può uccidere tutto il gruppo. Basta un giocatore per pozza.|n• Stai DIETRO il dragonhawk. Il suo {SPELL:1291519} frontale è letale e continua a bruciare dopo il colpo.|n• {SPELL:1291733}: va in enrage e attacca più veloce per 15 secondi. Se la tua classe può rimuovere un Enrage, fallo ora.|n• Solo con la challenge Malevolent Boons: un Dark Obelisk vicino gli dà il 15% di vita e danni in più e un incantesimo extra. Distruggi gli obelisk prima del fight e non arriva nessuno dei tre qui sotto.|n• {SPELL:1284125}: una nebula intrappola un giocatore a caso. Fa male ogni secondo e ti rallenta del 40%. Non puoi uscirne camminando finché è viva, quindi uccidi la nebula.|n• {SPELL:1284085}: compaiono specchi void che lanciano {SPELL:1284083}, un cast di 12 secondi che colpisce tutti entro 100 yard. Non puoi scappare. Interrompilo una volta e lo specchio sparisce.|n• {SPELL:1284064}: ondate di void che fanno male in fretta e ti spingono via.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Pozze rosse: Mettiti in una pozza rossa così non esplode su tutti.|nSoffio: Stai dietro il dragonhawk, il suo soffio davanti è letale.|nObelisk: Con Malevolent Boons attiva, distruggi prima i Dark Obelisk, così non ottiene incantesimi extra.",
	RITUAL_BOSS_GERLOK_STEPS = "• Chiama degli aiutanti e li potenzia con {SPELL:1277776}: colpiscono più forte e non si possono stordire, rallentare né radicare. Finché dura, lui subisce il 90% di danni in meno ({SPELL:1279189}). Uccidi gli aiutanti appena arrivano.|n• {SPELL:1278896}: il fuoco cade a terra e continua a bruciare. Esci subito, quasi ti uccide in un colpo.|n• {SPELL:1277559} è IL cast da interrompere: un grosso colpo su tutti entro 50 yard, e i pilastri non lo bloccano. Non tutti i cast si possono kickare, quindi tieni l'interrupt per questo.|n• {SPELL:1279288} viene spammato su un giocatore. Spezza la linea di vista dietro i pilastri.|n• Tienilo SULLA sua piattaforma. Tirarlo giù o fuori resetta il fight (Rob, live). Lo spazio è stretto, ma non cercare spazio al piano di sotto.|n• Challenge Embers: gli Embers lasciati accesi lo rendono molto più forte. Un giocatore su Wowhead ha visto circa il 60% di vita e danni in più con tutti e quattro attivi. Uccidi i mob marcati intorno a ogni Ember prima del boss per spegnerlo.",
	RITUAL_BOSS_GERLOK_QUICK = "Add: Uccidi subito i suoi aiutanti, perché finché vivono non subisce quasi danni.|nKick: Tieni l'interrupt per Shadowbolt Volley, il suo colpo forte su tutti.|nPilastri: Nasconditi dietro un pilastro così il suo Shadow Blast non ti colpisce.",
	RITUAL_BOSS_MINDBREAKER_QUICK = "Obelisk: Con Malevolent Boons attiva, distruggi prima i Dark Obelisk, così non ottiene incantesimi extra.|nSpecchi: Se compaiono specchi void, interrompi ognuno una volta e sparisce.|nSfere: Continua a passare sulle sfere di cura.",
	RITUAL_BOSS_SELENVJAR_QUICK = "Tridente: Se sei marcato, vai al bordo così il tridente cade lontano dal fight.|nRisucchio: Quando i tridenti ti attirano, allontanati da loro.|nFulmine: In gruppo, sparpagliatevi così la sua Chain Lightning colpisce meno giocatori.",
	RAID_BOSS_ROTMIRE_STEPS = "• Un solo boss e un ciclo che si ripete finché non muore. Brama di Sangue al pull. Ogni {SPELL:1221787} aggiunge uno stack di Rotting Pustules che resta, quindi il danno al raid continua a salire: più dura il fight, più è difficile.|n• {SPELL:1221622}: dei cerchi a terra mostrano dove compaiono gli add. Esci dai cerchi, o vieni sbalzato via e ferito gravemente. Ogni add (Shroomling) insegue un giocatore: portalo in un unico mucchio stretto vicino al boss, così il raid li uccide tutti insieme.|n• Uccidi ogni add prima che la barra di energia del boss sia piena. A 100 di energia lancia {SPELL:1221637}: un colpo su tutti, un knockback e un DoT di 16 secondi. Un add ancora vivo in quel momento ottiene Fungal Frenzy: vita piena, e non si può più stordire né interrompere.|n• Dopo {SPELL:1221637} ogni cadavere di add diventa un Bursting Shroom. Uccidili tutti entro circa 16 secondi: ognuno rimasto esplode su tutto il raid, e più di un'esplosione di solito è un wipe. Ecco perché gli add muoiono in un unico mucchio.|n• {SPELL:1222088} rallenta alcuni giocatori e li ferisce. Vai al bordo della stanza prima che finisca: lascia una chiazza ({SPELL:1222129}) che resta. Tieni liberi il centro e il mucchio di add, ed esci da ogni chiazza.|n• In Eroico e Mitico: compare anche un add Sporecap che non si muove. Interrompi il suo Poison Burst ogni singola volta, o tutto il raid accumula un DoT. Porta gli altri add da lui e uccidili lì.|n• In Mitico: arrivano anche i Funglings. Un cadavere di Shroomling entro 10 yard da un cadavere di Fungling crea un Bursting Doom Shroom, e questo uccide tutto il raid. Uccidi i due tipi in due punti separati.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Uccidi ogni add nel mucchio prima che la barra del boss sia piena, poi uccidi subito i funghi.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "Il danno cresce a ogni ciclo, quindi tieni i cooldown per il colpo forte quando la sua barra è piena.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Scambiati con l'altro tank dopo ogni pugno forte, e tieni il boss vicino al mucchio di add.",
	RAID_BOSS_ROTMIRE_QUICK = "Add: Metti i piccoli add fungo in un solo mucchio e uccidili prima che la barra del boss sia piena.|nFunghi: Quando la barra è piena gli add morti diventano funghi, quindi uccidili subito prima che esplodano.|nViticci: Se dei viticci ti rallentano, vai al bordo della stanza così la chiazza che lasciano non dà fastidio.",
	RAID_BOSS_ROTMIRE_TANK = "• Scambiati con l'altro tank dopo ogni {SPELL:1221781}: ti lancia in aria e ti fa subire più danni fisici per 14 secondi (35% in Normale, 75% in Eroico e Mitico). Usa una difensiva per il colpo.|n• Tieni il boss accanto al mucchio di add, così il raid lo colpisce mentre uccide gli add. In Eroico e Mitico: portalo dallo Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• Il danno al raid sale per tutto il fight: ogni {SPELL:1221787} aggiunge uno stack di Rotting Pustules, quindi ogni ciclo è più duro del precedente.|n• Pianifica i cooldown del raid per {SPELL:1221637} (un colpo più un DoT di 16 secondi su tutti) e per ogni Bursting Shroom che esplode.|n• Il tank colpito da {SPELL:1221781} subisce molti più danni fisici per 14 secondi.",
	RAID_BOSS_ROTMIRE_DPS = "• Colpisci gli add in cleave nel loro mucchio, e falli morire tutti prima di {SPELL:1221637}. Poi passa subito sui Bursting Shrooms.|n• In Eroico e Mitico: interrompi il Poison Burst dello Sporecap ogni volta.|n• In Mitico: Shroomlings e Funglings muoiono in due punti separati, ad almeno 10 yard di distanza.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100L’ingresso è SOTT’ACQUA|r — una grotta sommersa, quindi la barra del respiro scorre prima ancora del combattimento. All’ingresso ci sono bolle d’aria per ricaricarla.|n• Un boss, un ciclo che si ripete finché non muore. Conta per la riga Raid della tua Great Vault.|n• |cffffd100I murloc sono il combattimento.|r {SPELL:1257717} mette una grande bolla al centro e i murloc corrono verso di essa. Uccidili o rallentali PRIMA che ci arrivino — ognuno che entra diventa un Berserker che colpisce tutto il gruppo ogni 3 secondi. Porta il boss verso il gruppo più grande; i ranged pensano agli isolati.|n• Dei vortici circondano la stanza con un solo varco — raggruppatevi nel varco.|n• Quando un vortice raggiunge la bolla, scoppia: danni a tutti e un respingimento. Mettiti in modo da non essere scaraventato in acqua — ci sono gli squali.|n• {SPELL:1313393}: se ti colpisce, lasci sfere di gelo dove cammini. Mettile vicine, lontano dalla bolla e dai percorsi. In Normale non toccarle (danni che si accumulano e ghiaccio scivoloso); in Eroico e Mitico vanno raccolte, altrimenti esplodono su tutto il gruppo.|n• {SPELL:1260837} sono quattro secondi di danni a tutti — un cooldown di cura. In Eroico e Mitico ognuno la fa colpire più forte: l’enrage lento.|n• Dopo 10 minuti arriva l’enrage finale: il pull è finito.|n• Brama di Sangue al pull.|n• Dalle guide live e dal modulo DBM attuale, non ancora provato da noi — raccontaci cosa hai visto.",
	RAID_BOSS_NYMRISSA_TANK = "• Normale ed Eroico: {SPELL:1282937} sono diversi secondi di colpi pesanti su di te — usa una difensiva. Niente da orientare.|n• Mitico: {SPELL:1268562} è una linea che ti spinge indietro e si accumula; puntala lontano dal gruppo (attraverso le chiazze di ghiaccio, le lava via) e scambiati con l’altro tank sugli accumuli.|n• Tienila vicino al gruppo di murloc più grande, mai sopra la bolla.",
	RAID_BOSS_NYMRISSA_HEALER = "• Pianifica i cooldown per {SPELL:1260837} (quattro secondi su tutti) e per lo scoppio della bolla. Entrambi prevedibili.|n• Un Berserker murloc colpisce tutto il gruppo ogni 3 secondi finché non muore — un murloc sfuggito è dove le cure crollano.",
	RAID_BOSS_NYMRISSA_DPS = "• Sempre prima i murloc: uccidili o rallentali prima della bolla; stordimenti, radici e respingimenti funzionano. Un Berserker muore subito.|n• Mitico: prima il Frostscale — fa subire ai murloc intorno il 99% di danni in meno.|n• Poi di nuovo sul boss.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker: il boss della fase 2 di Daggerspine Point (Beast From the Deep). Lady Selen'vjar lo carica con magia void rubata.|n• {SPELL:1282587}: per 4 secondi fa male a un giocatore e a tutti entro 6 yard da lui. Non stare vicino a quel giocatore.|n• {SPELL:1282589}: evoca Visions of Madness e lascia zone che fanno male ogni secondo. Esci.|n• {SPELL:1282588}: i suoi alleati entro 20 yard subiscono il 25% di danni in meno per 10 secondi. Se puoi purgare la Magia, toglilo.|n• {SPELL:1282593}: una Maledizione che rende i tuoi attacchi e cast più lenti del 20% per un minuto. Rimuovila se puoi.|n• Solo con la challenge Malevolent Boons: un Dark Obelisk vicino gli dà il 15% di vita e danni in più, più {SPELL:1284125}, {SPELL:1284085} o {SPELL:1284064}. I suoi specchi void arrivano spesso a tre per volta: interrompi ognuno una volta e sparisce. Distruggi prima gli obelisk e non arriva niente di tutto questo.|n• Un giocatore su Wowhead: continua a passare sulle sfere di cura.|n• Dalla lista degli incantesimi di Wowhead, non ancora provato da noi. Raccontaci cosa hai visto.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar: leader dei naga e boss finale di Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Fasi: 1) Ritual Roles: i suoi capitani sorvegliano il rituale e drenano essenza void. 2) Beast From the Deep: potenzia un Mindbreaker. 3) Summoner's Fall: ti affronta di persona.|n• {SPELL:1280255}: un giocatore riceve un segno Targeted!, poi lei lancia lì un tridente. Colpisce tutti entro 8 yard e continua a fulminare chi gli sta vicino per un minuto. Se sei marcato, vai al bordo così il tridente cade lontano dal fight.|n• {SPELL:1282365}: per 8 secondi ogni tridente a terra attira i giocatori e li ferisce. Allontanati dai tridenti.|n• {SPELL:1272067} salta su un massimo di 3 giocatori. In gruppo, sparpagliatevi.|n• {SPELL:1281803}: si protegge con uno scudo. Quando lo scudo si rompe, compare un Water Torrent.|n• I giocatori su Wowhead la trovano molto più facile di Faithbreaker Ger'lok.|n• Dalla lista degli incantesimi di Wowhead, non ancora provato da noi. Raccontaci cosa hai visto.",
	RITUAL_ALERT_BINDING_NEBULA = "Binding Nebula! -> uccidi la nebula",
	RITUAL_ALERT_SHADOWBOLT = "Interrompi Shadowbolt Volley!",
	RITUAL_ALERT_DISSONANT = "Interrompi Dissonant Realities!",

	-- Challenge --------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• I tendril afferranti spawnano con un cerchio verde vorticoso — esci o vieni radicato e subisci danni.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Saccheggia un Ritual Chest alla fine di un sito qualsiasi, poi consegna la quest \"Ritual Site Challenge Report: Tendrils\".",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Compaiono degli spiriti che iniziano un cast lungo. Ferma il cast e lo spirito sparisce: funziona un interrupt, e anche stun, fear e altro crowd control. Se lo lasci finire, subisci la sua magia logorante.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Completa un sito Tier 3, poi parla con Ranger Captain Lilatha a Silvermoon (il tier richiesto cala ogni settimana).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Uccidere i nemici evoca rinforzi; più grande e forte è il pull che uccidi, più forti sono gli add.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Completa un sito Tier 4, poi parla con Lady Darkglen a Silvermoon (il tier richiesto cala ogni settimana).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• I dark obelisk buffano i nemici vicini — distruggi gli obelisk per rimuovere i buff.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Completa un sito Tier 2 per una quest da Lady Darkglen, poi esamina 5 Dark Obelisk dentro un sito (il tier richiesto cala ogni settimana).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• I nemici uccisi lasciano una pozza di magia void letale — spostati fuori da essa.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Saccheggia un Tainted Bone Pile dentro un sito Tier 2+ (vedi le note sul sito per la posizione), poi consegna la quest.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Nemici extra sono distribuiti per tutto il sito — aspettati pack più fitti.|n• Aumenta gli Spoils mentre è attiva (uno dei boost maggiori).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Completa un sito Tier 2, poi parla con Ranger Captain Lilatha a Silvermoon (il tier richiesto cala ogni settimana).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Nemici elite pattugliano il sito — evita i loro percorsi quando puoi.|n• Aumenta gli Spoils mentre è attiva.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procura\" tesori unici da un sito Tier 3+ (il tier richiesto cala ogni settimana).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Nemici casuali E il boss finale sono potenziati, segnalati da un orb fluttuante sopra di loro.|n• Aumenta gli Spoils mentre è attiva (uno dei boost maggiori).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Saccheggia un Ember of Power dentro un sito Tier 4 per iniziare la quest (il tier richiesto cala ogni settimana).",
})

