	-- Weekly hint (waarom de Ritual-weekly nog niet gedaan is)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Gegrendeld: %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Gegrendeld — ontgrendel Ritual Sites via de intro-questlijn in Silvermoon.",
	RITUAL_WEEKLY_HINT_PICKUP = "Nog niet opgepakt — deze weekly krijg je van Lady Liadrin in Silvermoon, en alleen in weken dat ze hem als een van haar vier keuzes aanbiedt.",
	RITUAL_WEEKLY_HINT_INTRO = "Dit personage heeft de intro-questlijn nog niet af — start \"Ranger Captain's Summons\" bij Ranger Captain Lilatha in Silvermoon (de Void Strike-stap doe je in de actieve assault-zone).",
	RITUAL_INTRO_STEP_FMT = "Introlijn op dit personage — stap %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(staat al in je questlog)",
	RITUAL_INTRO_STEP_SUMMONS = "start \"Ranger Captain's Summons\" bij Ranger Captain Lilatha, staging grounds boven de Bazaar.",
	RITUAL_INTRO_STEP_ALLIES = "doe \"Outfitting and Allies\" — maak kennis met de bondgenoten bij Lilatha's staging grounds.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — deze stap speelt zich af in de actieve assault-zone (zie Void Assaults hieronder).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — onderzoek de Ritual Site-rapporten en verstoor daarna een Ritual Site.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — meld je bij Lady Darkglen bij de hub.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "Staat in je questlog — afmaken en inleveren.",

	-- Intro / hoe het werkt --------------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Kies je tier bij de Curious Obelisk; elke tier moet gecleard zijn om de volgende te ontgrendelen.|n• De obelisk noemt wat elke tier vraagt: Tier 3 vereist 1 actieve challenge, Tier 4 vereist er 2, Tier 5 vereist er 4, Tier 6 vereist er 6.|n• Hogere tiers geven meer Spoils en renown. Aanbevolen item level, op 20 augustus van de obelisk zelf afgelezen: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Hou een tier in de dropdown aan om het zelf na te kijken — deze getallen schuiven per seizoen.",
	RITUAL_TIP_INTRO_SCORING = "• Spoils zijn je score; de Ritual Chest aan het eind schaalt ermee.|n• Doden: de eerste 2 zijn gratis, daarna kost elke dood 5% Spoils, tot maximaal -50%.|n• Schone clears verslaan snelle pulls — doodgaan kost direct beloning.",
	RITUAL_TIP_INTRO_WEEKLY = "• Bij de start zakte de tier die nodig is om een challenge te ONTGRENDELEN elke week met één. Dat loopt al maanden, dus een lage tier is nu hoogstwaarschijnlijk genoeg.|n• Telt mee voor de World-rij van de Great Vault, net als een Delve van dezelfde tier.|n• Renown-boosters: Ritual Tablet (eerste site van de week), Ritual Tablet Fragment (tweede site), en Ritual Site Reports (schaalt met je Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• In combat verschijnen Regeneration Orbs die 15% van je health healen (Renown 1).|n• Orb Potency (Renown 4) verhoogt die healing.|n• Leun op de orbs in plaats van cooldowns te verbranden aan zelf-healing.",

	-- Daggerspine Point (Eversong Woods) -------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, aan de westkust bij Goldenmist Village.|n• Vijanden: naga.|n• Eén week per keer actief; de obelisk heeft een paars icoon op de map.|n• Ga naar de Curious Obelisk en kies daar je tier + challenges.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Een korte instanced scenario in drie fases: dood de named elites verspreid over de site, dan de Void-Infused Mindbreaker, dan Lady Selen'vjar zelf.|n• Scenario gezien bij de obelisk: “A Strike From the Sea”.|n• Na de kill loot je Lady Selen'vjar's Ritual Chest en ga je weg via de Obelisk Portal achter het gebouw.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (ontgrendelt de Tainted Corpses-challenge): /way 66.09 62.58.|n• Dark Obelisks (Malevolent Boons-quest — onderzoek er 5 van de 9): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• Kleine treasures en Regeneration Orbs liggen verspreid door de site.",

	-- Broken Throne (Zul'Aman) -----------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, in het zuiden van de zone.|n• Vijanden: Twilight's Blade-cultisten.|n• Eén week per keer actief; de obelisk heeft een paars icoon op de map.|n• Ga naar de Curious Obelisk en kies daar je tier + challenges.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Een kort scenario in drie stappen: dood de benoemde vijanden rond de site, dan de Corrupted Amani Dragonhawk, dan Faithbreaker Ger'lok in het gebouw.|n• Scenario bij de obelisk: “A Corrupted Path”.|n• Corrupted Amani Dragonhawk: ga in de kleine rode plassen staan (Volatile Plumage), anders ontploffen ze op de hele groep, en sta nooit vóór zijn Shadowflame Breath.|n• Alleen met de challenge Malevolent Boons: Dark Obelisks geven de vijanden extra spells, zoals een Binding Nebula die je vasthoudt tot je hem doodt, en void-spiegels waarvan je de cast moet interrupten. Sloop eerst de obelisks, dan komt dat allemaal niet.|n• Loot daarna de Ritual Chest van Faithbreaker Ger'lok.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (ontgrendelt de Tainted Corpses-challenge): /way 47.91 36.52.|n• Dark Obelisks (Malevolent Boons-quest — onderzoek er 5 van de 9): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54 · 50/57 · 45/64 · 47/76.|n• De Dark Obelisks slopen haalt de buffs weg die de vijanden versterken — ze clearen maakt de bazen merkbaar makkelijker (laat ze alleen staan als je voor de no-obelisk-achievement gaat).|n• Kleine treasures en Regeneration Orbs liggen verspreid door de site.",
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291559} laat kleine RODE PLASSEN vallen. Ga in een plas staan om hem te soaken: je krijgt maar een kleine tik. Een plas waar niemand in staat ontploft voor enorme Shadowflame-schade en kan de hele groep doden. Eén speler per plas is genoeg.|n• Ga ACHTER de dragonhawk staan. Zijn frontale {SPELL:1291519} is dodelijk en blijft na de klap nog branden.|n• {SPELL:1291733}: hij wordt enraged en valt 15 seconden lang sneller aan. Kan jouw class een Enrage weghalen, doe het dan nu.|n• Alleen met de Malevolent Boons-challenge: een Dark Obelisk in de buurt geeft hem 15% meer health en schade en één extra spell. Sla de obelisks vóór het gevecht kapot, dan komt geen van de drie hieronder.|n• {SPELL:1284125}: een nebula zet een willekeurige speler vast. Die doet elke seconde pijn en vertraagt je met 40%. Je kunt er niet uit lopen zolang hij leeft, dus sla de nebula kapot.|n• {SPELL:1284085}: er verschijnen void-spiegels die {SPELL:1284083} casten, een cast van 12 seconden die iedereen binnen 100 yards raakt. Wegrennen kan niet. Interrupt hem één keer en de spiegel verdwijnt.|n• {SPELL:1284064}: void-golven die snel pijn doen en je wegduwen.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Rode plassen: Ga in een rode plas staan zodat hij niet op iedereen ontploft.|nAdem: Ga achter de dragonhawk staan, zijn adem aan de voorkant is dodelijk.|nObelisks: Staat Malevolent Boons aan, sla dan eerst de Dark Obelisks kapot, dan krijgt hij geen extra spells.",
	RITUAL_BOSS_GERLOK_STEPS = "• Hij roept helpers op en versterkt ze met {SPELL:1277776}: ze slaan harder en kunnen niet gestund, vertraagd of geroot worden. Zolang dat duurt krijgt hij 90% minder schade ({SPELL:1279189}). Dood de helpers zodra ze er zijn.|n• {SPELL:1278896}: er landt vuur op de grond dat blijft branden. Stap er meteen uit, het doodt je bijna in één keer.|n• {SPELL:1277559} is DÉ cast om te interrupten: een grote klap op iedereen binnen 50 yards, en pilaren houden hem niet tegen. Niet elke cast is kickbaar, dus bewaar je interrupt hiervoor.|n• {SPELL:1279288} wordt op één speler gespamd. Breek line of sight achter de pilaren.|n• Houd hem ÓP zijn platform. Pull je hem naar beneden of eraf, dan reset het gevecht (Rob, live). Het is krap, maar zoek geen ruimte beneden.|n• Embers-challenge: Embers die blijven branden maken hem veel sterker. Eén speler op Wowhead zag zo'n 60% meer health en schade met alle vier aan. Dood de gemarkeerde mobs rond elke Ember vóór de baas om hem te doven.",
	RITUAL_BOSS_GERLOK_QUICK = "Adds: Dood zijn helpers meteen, want zolang ze leven krijgt hij bijna geen schade.|nKick: Bewaar je interrupt voor Shadowbolt Volley, zijn grote klap op iedereen.|nPilaren: Verstop je achter een pilaar zodat zijn Shadow Blast je niet kan raken.",
	RITUAL_BOSS_MINDBREAKER_QUICK = "Obelisks: Staat Malevolent Boons aan, sla dan eerst de Dark Obelisks kapot, dan krijgt hij geen extra spells.|nSpiegels: Verschijnen er void-spiegels, interrupt elke spiegel één keer en hij verdwijnt.|nBollen: Blijf over de heal-bollen lopen.",
	RITUAL_BOSS_SELENVJAR_QUICK = "Trident: Ben je gemarkeerd, loop dan naar de rand zodat de trident buiten het gevecht landt.|nTrekken: Trekken de tridents je naar zich toe, loop er dan van weg.|nBliksem: Ga in een groep verspreid staan zodat haar Chain Lightning minder spelers raakt.",
	RAID_BOSS_ROTMIRE_STEPS = "• Eén baas en één ronde die zich herhaalt tot hij dood is. Bloodlust bij de pull. Elke {SPELL:1221787} geeft een Rotting Pustules-stack die blijft, dus de raid-schade blijft stijgen: hoe langer het gevecht, hoe zwaarder.|n• {SPELL:1221622}: cirkels op de grond laten zien waar adds verschijnen. Stap eruit, anders word je weggeslingerd en flink geraakt. Elke add (Shroomling) jaagt op één speler: loop hem naar één strakke hoop bij de baas, zodat de raid ze allemaal tegelijk doodt.|n• Dood elke add voordat de energiebalk van de baas vol is. Bij 100 energie cast hij {SPELL:1221637}: een klap op iedereen, een knockback en een DoT van 16 seconden. Een add die dan nog leeft krijgt Fungal Frenzy: volle health, en hij kan niet meer gestund of geïnterrupt worden.|n• Na {SPELL:1221637} groeit elk add-lijk uit tot een Bursting Shroom. Dood ze allemaal binnen zo'n 16 seconden: elke die blijft staan ontploft op de hele raid, en meer dan één ontploffing is meestal een wipe. Daarom gaan de adds dood op één hoop.|n• {SPELL:1222088} vertraagt een paar spelers en doet ze pijn. Loop naar de rand van de ruimte voordat het afloopt: het laat een plek ({SPELL:1222129}) achter die blijft. Houd het midden en de add-hoop vrij, en stap uit elke plek.|n• Op Heroic en Mythic: er verschijnt ook een Sporecap-add die niet beweegt. Interrupt zijn Poison Burst elke keer, anders stapelt de hele raid een DoT. Breng de andere adds naar hem toe en dood ze daar.|n• Op Mythic: er komen ook Funglings. Een Shroomling-lijk binnen 10 yards van een Fungling-lijk maakt een Bursting Doom Shroom, en dan wipet de raid. Dood de twee soorten op twee aparte plekken.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Dood elke add op de hoop voordat de balk van de baas vol is, en dood dan meteen de paddenstoelen.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "De schade wordt elke ronde groter, dus plan cooldowns voor de grote klap als zijn balk vol is.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Wissel met de andere tank na elke harde klap, en houd de baas bij de add-hoop.",
	RAID_BOSS_ROTMIRE_QUICK = "Adds: Trek de kleine paddenstoel-adds naar één hoop en dood ze voordat de balk van de baas vol is.|nPaddenstoelen: Is zijn balk vol, dan groeien dode adds uit tot paddenstoelen, dus dood die snel voordat ze ontploffen.|nRanken: Vertragen ranken je, loop dan naar de rand van de ruimte zodat hun plek niet in de weg ligt.",
	RAID_BOSS_ROTMIRE_TANK = "• Wissel met de andere tank na elke {SPELL:1221781}: die gooit je omhoog en laat je 14 seconden lang meer fysieke schade krijgen (35% op Normal, 75% op Heroic en Mythic). Gebruik een defensive voor de klap.|n• Houd de baas naast de add-hoop, zodat de raid hem raakt terwijl ze de adds doden. Op Heroic en Mythic: breng hem naar de Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• De raid-schade stijgt het hele gevecht: elke {SPELL:1221787} geeft een Rotting Pustules-stack, dus elke ronde is zwaarder dan de vorige.|n• Plan raid-cooldowns voor {SPELL:1221637} (een klap plus een DoT van 16 seconden op iedereen) en voor elke Bursting Shroom die ontploft.|n• De tank die door {SPELL:1221781} geraakt wordt, krijgt 14 seconden lang veel meer fysieke schade.",
	RAID_BOSS_ROTMIRE_DPS = "• Cleave de adds op hun hoop, en zorg dat ze allemaal dood zijn vóór {SPELL:1221637}. Switch dan meteen naar de Bursting Shrooms.|n• Op Heroic en Mythic: interrupt de Poison Burst van de Sporecap elke keer.|n• Op Mythic: Shroomlings en Funglings gaan dood op twee aparte plekken, minstens 10 yards uit elkaar.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100De ingang is ONDER WATER|r — een grot onder water, dus je adembalk loopt al voordat het gevecht begint. Bij de ingang hangen luchtbellen om hem bij te vullen.|n• Eén baas, één ronde die zich herhaalt tot ze dood is. Telt voor de Raid-rij van je Great Vault.|n• |cffffd100De murlocs zijn het gevecht.|r {SPELL:1257717} zet een grote bel in het midden en murlocs rennen erheen. Dood of vertraag ze VOORDAT ze erin zijn — elke murloc die binnenkomt wordt een Berserker die de hele groep elke 3 seconden raakt. Zet de baas bij de grootste groep; ranged pakt de losse.|n• Draaikolken cirkelen door de ruimte met één gat ertussen — ga allemaal in dat gat staan.|n• Raakt een draaikolk de bel, dan knalt die: schade op iedereen plus een duw. Sta zo dat je niet het water in vliegt — daar zitten haaien.|n• {SPELL:1313393}: raakt het jou, dan laat je ijsbollen achter waar je loopt. Leg ze bij elkaar, weg van de bel en de looproutes. Op Normal raak je ze niet aan (stapelende schade en glad ijs); op Heroic en Mythic moeten ze juist opgepakt worden, anders spatten ze uiteen op de hele groep.|n• {SPELL:1260837} is vier seconden schade op iedereen — een healer-cooldown. Op Heroic en Mythic maakt elke keer haar klappen harder: de langzame soft enrage.|n• Na 10 minuten komt de harde enrage: dan is de pull voorbij.|n• Bloodlust bij de pull.|n• Uit de live-gidsen en de huidige DBM-mod, nog niet door ons zelf gelopen — vertel ons wat je zag.",
	RAID_BOSS_NYMRISSA_TANK = "• Normal en Heroic: {SPELL:1282937} is een paar seconden harde klappen op jou — gebruik een defensive. Er valt niets te richten.|n• Mythic: {SPELL:1268562} is een lijn die je terugduwt en stapelt; richt hem weg van de groep (door de ijsvlekken, die spoelt hij weg) en wissel met de andere tank op de stacks.|n• Houd haar bij de grootste groep murlocs, nooit boven op de bel.",
	RAID_BOSS_NYMRISSA_HEALER = "• Plan cooldowns voor {SPELL:1260837} (vier seconden op iedereen) en voor het knallen van de bel. Allebei voorspelbaar.|n• Een murloc-Berserker raakt de hele groep elke 3 seconden tot hij dood is — een gemiste murloc is waar het healen misgaat.",
	RAID_BOSS_NYMRISSA_DPS = "• Altijd eerst de murlocs: dood of vertraag ze voordat ze bij de bel zijn; stuns, roots en knockbacks werken. Een Berserker gaat meteen dood.|n• Mythic: eerst de Frostscale — die laat de murlocs om zich heen 99% minder schade krijgen.|n• Daarna terug op de baas.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker: de baas van fase 2 in Daggerspine Point (Beast From the Deep). Lady Selen'vjar laadt hem op met gestolen void-magie.|n• {SPELL:1282587}: 4 seconden lang doet hij pijn bij één speler en bij iedereen binnen 6 yards van die speler. Ga niet naast die speler staan.|n• {SPELL:1282589}: hij roept Visions of Madness op en laat plekken achter die elke seconde pijn doen. Stap eruit.|n• {SPELL:1282588}: zijn bondgenoten binnen 20 yards krijgen 10 seconden lang 25% minder schade. Kun je Magic purgen, haal het dan weg.|n• {SPELL:1282593}: een Curse die je aanvallen en casts een minuut lang 20% trager maakt. Haal hem weg als je kunt.|n• Alleen met de Malevolent Boons-challenge: een Dark Obelisk in de buurt geeft hem 15% meer health en schade plus {SPELL:1284125}, {SPELL:1284085} of {SPELL:1284064}. Zijn void-spiegels komen vaak met drie tegelijk: interrupt elke spiegel één keer en hij verdwijnt. Sla de obelisks eerst kapot, dan komt hier niets van.|n• Eén speler op Wowhead: blijf over de heal-bollen lopen.|n• Uit de spell-lijst van Wowhead, nog niet door ons zelf gelopen. Vertel ons wat je zag.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar: naga-leider en eindbaas van Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Fases: 1) Ritual Roles: haar captains bewaken het ritueel en draineren void-essentie. 2) Beast From the Deep: ze versterkt een Mindbreaker. 3) Summoner's Fall: ze vecht zelf tegen je.|n• {SPELL:1280255}: een speler krijgt een Targeted!-markering, daarna gooit ze daar een trident heen. Die raakt iedereen binnen 8 yards en blijft een minuut lang iedereen in de buurt shocken. Ben jij gemarkeerd, loop dan naar de rand zodat de trident buiten het gevecht landt.|n• {SPELL:1282365}: 8 seconden lang trekt elke trident op de grond spelers naar zich toe en doet ze pijn. Loop weg van de tridents.|n• {SPELL:1272067} springt over naar maximaal 3 spelers. In een groep: ga verspreid staan.|n• {SPELL:1281803}: ze zet een schild op. Breekt het schild, dan verschijnt er een Water Torrent.|n• Spelers op Wowhead noemen haar veel makkelijker dan Faithbreaker Ger'lok.|n• Uit de spell-lijst van Wowhead, nog niet door ons zelf gelopen. Vertel ons wat je zag.",
	RITUAL_ALERT_BINDING_NEBULA = "Binding Nebula! -> sla de nebula kapot",
	RITUAL_ALERT_SHADOWBOLT = "Interrupt Shadowbolt Volley!",
	RITUAL_ALERT_DISSONANT = "Interrupt Dissonant Realities!",

	-- Challenges -------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• Grijpende tendrils verschijnen met een draaiende groene cirkel — eruit lopen, anders word je geroot en neem je schade.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Loot een Ritual Chest aan het eind van een site en lever de quest \"Ritual Site Challenge Report: Tendrils\" in.",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Er verschijnen geesten die een lange cast starten. Stop de cast en de geest verdwijnt: een interrupt werkt, en stuns, fears en andere crowd control ook. Laat je hem afmaken, dan krijg je zijn withering-magie.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Clear een Tier 3-site en praat dan met Ranger Captain Lilatha in Silvermoon (de vereiste tier zakt elke week).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Kills summonen reinforcements; hoe groter en sterker de pull die je doodt, hoe sterker de adds.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Clear een Tier 4-site en praat dan met Lady Darkglen in Silvermoon (de vereiste tier zakt elke week).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Dark obelisks buffen vijanden in de buurt — vernietig de obelisks om de buffs weg te halen.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Clear een Tier 2-site voor een quest van Lady Darkglen en investigeer dan 5 Dark Obelisks in een site (de vereiste tier zakt elke week).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Gedode vijanden laten een plas dodelijke void-magie achter — eruit bewegen.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Loot een Tainted Bone Pile in een Tier 2+-site (zie de site-notities voor de locatie) en lever de quest in.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Extra vijanden verspreid door de hele site — reken op dichtere packs.|n• Verhoogt Spoils zolang actief (een van de grotere boosts).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Clear een Tier 2-site en praat dan met Ranger Captain Lilatha in Silvermoon (de vereiste tier zakt elke week).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Elite-vijanden patrouilleren door de site — vermijd hun routes waar het kan.|n• Verhoogt Spoils zolang actief.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procure\" unieke treasures uit een Tier 3+-site (de vereiste tier zakt elke week).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Random vijanden ÉN de eindboss zijn empowered, gemarkeerd met een zwevende orb erboven.|n• Verhoogt Spoils zolang actief (een van de grotere boosts).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Loot een Ember of Power in een Tier 4-site om de quest te starten (de vereiste tier zakt elke week).",
})

