	-- Weekly-Hinweis (warum die Ritual-Weekly noch offen ist)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Gesperrt: %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Gesperrt — schalte Ritual Sites über die Einstiegs-Questreihe in Silbermond frei.",
	RITUAL_WEEKLY_HINT_PICKUP = "Noch nicht angenommen — diese Wochenquest gibt es bei Lady Liadrin in Silbermond, und nur in Wochen, in denen sie sie als eine ihrer vier Auswahlen anbietet.",
	RITUAL_WEEKLY_HINT_INTRO = "Dieser Charakter hat die Einstiegs-Questreihe noch nicht abgeschlossen — starte \"Ranger Captain's Summons\" bei Ranger Captain Lilatha in Silbermond (der Void-Strike-Schritt passiert in der aktiven Angriffszone).",
	RITUAL_INTRO_STEP_FMT = "Einstiegs-Questreihe auf diesem Charakter — Schritt %d/%d: %s",
	RITUAL_INTRO_STEP_INLOG = "(bereits in deinem Questlog)",
	RITUAL_INTRO_STEP_SUMMONS = "starte \"Ranger Captain's Summons\" bei Ranger Captain Lilatha, Sammelplatz über dem Basar.",
	RITUAL_INTRO_STEP_ALLIES = "erledige \"Outfitting and Allies\" — triff die Verbündeten an Lilathas Sammelplatz.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — dieser Schritt findet in der aktiven Angriffszone statt (siehe Void Assaults unten).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — untersuche die Ritualstätten-Berichte und störe danach eine Ritualstätte.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — melde dich bei Lady Darkglen am Stützpunkt.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "Steht in deinem Questlog — abschließen und abgeben.",

	-- Intro / So funktioniert es -----------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Wähle deine Stufe am Curious Obelisk; schließe jede Stufe ab, um die nächste freizuschalten.|n• Der Obelisk nennt, was jede Stufe verlangt: Tier 3 braucht 1 aktive Challenge, Tier 4 braucht 2, Tier 5 braucht 4, Tier 6 braucht 6.|n• Höhere Stufen geben mehr Spoils und Ansehen. Vom Spiel empfohlene Gegenstandsstufe, am 20. August direkt am Obelisken abgelesen: |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Fahr im Dropdown über eine Stufe, um es selbst zu prüfen — diese Zahlen verschieben sich pro Saison.",
	RITUAL_TIP_INTRO_SCORING = "• Spoils sind deine Punktzahl; die Ritual Chest am Ende skaliert damit.|n• Tode: die ersten 2 sind frei, danach kostet jeder Tod 5% Spoils, bis maximal -50%.|n• Saubere Clears schlagen schnelle Pulls — Sterben kostet direkt Belohnung.",
	RITUAL_TIP_INTRO_WEEKLY = "• Zum Start sank die Stufe, die zum FREISCHALTEN einer Challenge nötig ist, jede Woche um eins. Das läuft schon seit Monaten, also reicht inzwischen sehr wahrscheinlich eine niedrige Stufe.|n• Zählt für die Welt-Reihe des Great Vault, wie ein Delve derselben Stufe.|n• Ansehen-Booster: Ritual Tablet (erste Stätte der Woche), Ritual Tablet Fragment (zweite Stätte) und Ritual Site Reports (skaliert mit deinen Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• Im Kampf erscheinen Regeneration Orbs, die 15% deiner Gesundheit heilen (Ansehen 1).|n• Orb Potency (Ansehen 4) erhöht diese Heilung.|n• Nutz die Orbs, statt Cooldowns für Selbstheilung zu verbrennen.",

	-- Daggerspine Point (Eversong Woods) ---------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, an der Westküste bei Goldenmist Village.|n• Gegner: Naga.|n• Jeweils eine Woche aktiv; der Obelisk zeigt ein violettes Symbol auf der Karte.|n• Betrete die Stätte am Curious Obelisk und wähle dort Stufe + Challenges.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Ein kurzes instanziertes Szenario in drei Phasen: Töte die benannten Elitegegner rund um die Stätte, dann den Void-Infused Mindbreaker, dann Lady Selen'vjar selbst.|n• Am Obelisken gesehenes Szenario: “A Strike From the Sea”.|n• Nach dem Kill lootest du die Ritual Chest von Lady Selen'vjar und gehst durch das Obelisk Portal hinter dem Gebäude hinaus.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (schaltet die Tainted-Corpses-Challenge frei): /way 66.09 62.58.|n• Dark Obelisks (Malevolent-Boons-Quest — untersuche 5 von 9): 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• Kleine Schätze und Regeneration Orbs sind über die Stätte verteilt.",

	-- Broken Throne (Zul'Aman) --------------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, im Süden der Zone.|n• Gegner: Kultisten der Twilight's Blade.|n• Jeweils eine Woche aktiv; der Obelisk zeigt ein violettes Symbol auf der Karte.|n• Betrete die Stätte am Curious Obelisk und wähle dort Stufe + Challenges.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Ein kurzes instanziertes Szenario in drei Phasen: Töte die benannten Gegner rund um die Stätte, dann den Corrupted Amani Dragonhawk, dann Faithbreaker Ger'lok im Gebäude.|n• Am Obelisken gesehenes Szenario: “A Corrupted Path”.|n• Corrupted Amani Dragonhawk: Stell dich in die kleinen roten Pfützen (Volatile Plumage), damit sie nicht auf die ganze Gruppe ausbrechen, und steh nie vor seinem Shadowflame Breath.|n• Nur mit der Malevolent-Boons-Challenge: Dark Obelisks geben den Gegnern zusätzliche Zauber, etwa eine Binding Nebula, die dich festhält, bis du sie tötest, und Leeren-Spiegel, deren Zauber du unterbrechen musst. Zerstöre zuerst die Obelisken, dann kommt nichts davon.|n• Danach lootest du die Ritual Chest von Faithbreaker Ger'lok.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (schaltet die Tainted-Corpses-Challenge frei): /way 47.91 36.52.|n• Dark Obelisks (Malevolent-Boons-Quest — untersuche 5 beliebige; 9 Spawns): 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54 · 50/57 · 45/64 · 47/76.|n• Das Zerstören der Dark Obelisks entzieht den Gegnern der Stätte die Buffs, die sie stärken — werden sie beseitigt, sind die Bosse deutlich leichter (lass sie nur stehen, wenn du den Erfolg ohne Obelisken anstrebst).|n• Kleine Schätze und Regeneration Orbs sind über die Stätte verteilt.",
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291559} legt kleine ROTE PFÜTZEN. Stell dich in eine, um sie zu soaken: Du bekommst nur einen kleinen Treffer. Eine Pfütze, in der niemand steht, explodiert mit gewaltigem Shadowflame-Schaden und kann die ganze Gruppe töten. Ein Spieler pro Pfütze reicht.|n• Stell dich HINTER den Drachenfalken. Sein frontaler {SPELL:1291519} ist tödlich und brennt nach dem Treffer weiter.|n• {SPELL:1291733}: Er wird wütend und greift 15 Sekunden lang schneller an. Kann deine Klasse einen Enrage-Effekt entfernen, tu es jetzt.|n• Nur mit der Malevolent-Boons-Challenge: Ein Dark Obelisk in der Nähe gibt ihm 15 % mehr Gesundheit und Schaden und einen zusätzlichen Zauber. Zerstöre die Obelisken vor dem Kampf, dann kommt keiner der drei unten.|n• {SPELL:1284125}: Ein Nebel hält einen zufälligen Spieler fest. Er schadet jede Sekunde und verlangsamt dich um 40 %. Solange er lebt, kannst du nicht hinauslaufen, also töte den Nebel.|n• {SPELL:1284085}: Leeren-Spiegel erscheinen und wirken {SPELL:1284083}, einen Zauber von 12 Sekunden, der alle im Umkreis von 100 Metern trifft. Weglaufen geht nicht. Unterbrich ihn einmal, und der Spiegel verschwindet.|n• {SPELL:1284064}: Leerenwellen, die schnell schaden und dich wegstoßen.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Rote Pfützen: Stell dich in eine rote Pfütze, damit sie nicht auf alle explodiert.|nAtem: Stell dich hinter den Drachenfalken, sein Atem nach vorn ist tödlich.|nObelisken: Ist Malevolent Boons an, zerstöre zuerst die Dark Obelisks, dann bekommt er keine zusätzlichen Zauber.",
	RITUAL_BOSS_GERLOK_STEPS = "• Er ruft Helfer und verstärkt sie mit {SPELL:1277776}: Sie schlagen härter und können nicht betäubt, verlangsamt oder festgewurzelt werden. Solange das dauert, nimmt er 90 % weniger Schaden ({SPELL:1279189}). Töte die Helfer, sobald sie kommen.|n• {SPELL:1278896}: Feuer landet auf dem Boden und brennt weiter. Geh sofort heraus, es tötet dich fast auf einen Schlag.|n• {SPELL:1277559} ist DER Zauber zum Unterbrechen: ein großer Treffer auf alle im Umkreis von 50 Metern, und Säulen halten ihn nicht auf. Nicht jeder Zauber ist unterbrechbar, also heb deinen Kick dafür auf.|n• {SPELL:1279288} wird auf einen Spieler gespammt. Brich die Sichtlinie hinter den Säulen.|n• Halte ihn AUF seiner Plattform. Ziehst du ihn nach unten oder von ihr herunter, setzt sich der Kampf zurück (Rob, live). Der Platz ist eng, aber such unten keinen Raum.|n• Embers-Challenge: Embers, die weiter brennen, machen ihn viel stärker. Ein Spieler auf Wowhead sah mit allen vier aktiv etwa 60 % mehr Gesundheit und Schaden. Töte die markierten Gegner um jedes Ember vor dem Boss, um es zu löschen.",
	RITUAL_BOSS_GERLOK_QUICK = "Adds: Töte seine Helfer sofort, denn solange sie leben, nimmt er fast keinen Schaden.|nKick: Heb deinen Kick für Shadowbolt Volley auf, seinen großen Treffer auf alle.|nSäulen: Versteck dich hinter einer Säule, damit sein Shadow Blast dich nicht trifft.",
	RITUAL_BOSS_MINDBREAKER_QUICK = "Obelisken: Ist Malevolent Boons an, zerstöre zuerst die Dark Obelisks, dann bekommt er keine zusätzlichen Zauber.|nSpiegel: Erscheinen Leeren-Spiegel, unterbrich jeden einmal, und er verschwindet.|nKugeln: Lauf immer wieder über die Heilkugeln.",
	RITUAL_BOSS_SELENVJAR_QUICK = "Dreizack: Bist du markiert, geh an den Rand, damit der Dreizack abseits vom Kampf landet.|nSog: Ziehen dich die Dreizacke heran, geh von ihnen weg.|nBlitz: Verteilt euch in einer Gruppe, damit ihr Chain Lightning weniger Spieler trifft.",
	RAID_BOSS_ROTMIRE_STEPS = "• Ein Boss und ein Ablauf, der sich wiederholt, bis er fällt. Kampfrausch beim Pull. Bei jedem {SPELL:1221787} kommt ein Stapel Rotting Pustules dazu, der bleibt, also steigt der Raidschaden immer weiter: Je länger der Kampf, desto härter.|n• {SPELL:1221622}: Kreise am Boden zeigen, wo Adds erscheinen. Geh aus ihnen heraus, sonst wirst du weggeschleudert und schwer verletzt. Jedes Add (Shroomling) jagt einen Spieler: Lauf mit ihm zu einem engen Haufen nahe am Boss, damit der Raid alle zusammen tötet.|n• Töte jedes Add, bevor die Energieleiste des Bosses voll ist. Bei 100 Energie wirkt er {SPELL:1221637}: ein Treffer auf alle, ein Rückstoß und ein DoT über 16 Sekunden. Ein Add, das dann noch lebt, bekommt Fungal Frenzy: volle Gesundheit, und es kann nicht mehr betäubt oder unterbrochen werden.|n• Nach {SPELL:1221637} wächst jede Add-Leiche zu einem Bursting Shroom. Töte alle innerhalb von etwa 16 Sekunden: Jeder übrige explodiert auf den ganzen Raid, und mehr als eine Explosion ist meist ein Wipe. Deshalb sterben die Adds auf einem Haufen.|n• {SPELL:1222088} verlangsamt ein paar Spieler und verletzt sie. Lauf an den Rand des Raums, bevor es endet: Es hinterlässt eine Fläche ({SPELL:1222129}), die bleibt. Halte die Mitte und den Add-Haufen frei, und geh aus jeder Fläche heraus.|n• Auf Heroisch und Mythisch: Zusätzlich erscheint ein Sporecap-Add, das sich nicht bewegt. Unterbrich seinen Poison Burst jedes einzelne Mal, sonst stapelt der ganze Raid einen DoT. Bring die anderen Adds zu ihm und töte sie dort.|n• Auf Mythisch: Auch Funglings kommen. Eine Shroomling-Leiche innerhalb von 10 Metern um eine Fungling-Leiche macht einen Bursting Doom Shroom, und das wipet den Raid. Töte die beiden Sorten an zwei getrennten Stellen.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Töte jedes Add im Haufen, bevor die Leiste des Bosses voll ist, und dann sofort die Pilze.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "Der Schaden wird mit jedem Durchlauf größer, also plane Cooldowns für den großen Treffer, wenn seine Leiste voll ist.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Wechsle nach jedem großen Schlag mit dem anderen Tank, und halte den Boss neben dem Add-Haufen.",
	RAID_BOSS_ROTMIRE_QUICK = "Adds: Zieh die kleinen Pilz-Adds auf einen Haufen und töte sie, bevor die Leiste des Bosses voll ist.|nPilze: Ist seine Leiste voll, werden tote Adds zu Pilzen, also töte die schnell, bevor sie explodieren.|nRanken: Wenn Ranken dich verlangsamen, lauf an den Rand des Raums, damit ihre Fläche nicht im Weg liegt.",
	RAID_BOSS_ROTMIRE_TANK = "• Wechsle nach jedem {SPELL:1221781} mit dem anderen Tank: Der Schlag wirft dich hoch und lässt dich 14 Sekunden lang mehr physischen Schaden nehmen (35 % auf Normal, 75 % auf Heroisch und Mythisch). Nutze eine Defensive dafür.|n• Halte den Boss neben dem Add-Haufen, damit der Raid ihn trifft, während er die Adds tötet. Auf Heroisch und Mythisch: Bring ihn zum Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• Der Raidschaden steigt den ganzen Kampf: Bei jedem {SPELL:1221787} kommt ein Stapel Rotting Pustules dazu, also ist jeder Durchlauf härter als der letzte.|n• Plane Raid-Cooldowns für {SPELL:1221637} (ein Treffer plus ein DoT über 16 Sekunden auf alle) und für jeden Bursting Shroom, der explodiert.|n• Der Tank, den {SPELL:1221781} trifft, nimmt 14 Sekunden lang viel mehr physischen Schaden.",
	RAID_BOSS_ROTMIRE_DPS = "• Cleave die Adds auf ihrem Haufen, und sorg dafür, dass alle vor {SPELL:1221637} tot sind. Dann wechsle sofort auf die Bursting Shrooms.|n• Auf Heroisch und Mythisch: Unterbrich den Poison Burst des Sporecaps jedes Mal.|n• Auf Mythisch: Shroomlings und Funglings sterben an zwei getrennten Stellen, mindestens 10 Meter auseinander.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100Der Eingang liegt UNTER WASSER|r — eine überflutete Höhle, deine Atemleiste läuft also schon vor dem Kampf. Am Eingang gibt es Luftblasen zum Auffüllen.|n• Ein Boss, ein Ablauf, der sich wiederholt, bis sie fällt. Zählt für die Raid-Reihe deiner Great Vault.|n• |cffffd100Die Murlocs sind der Kampf.|r {SPELL:1257717} setzt eine große Blase in die Mitte, und Murlocs rennen darauf zu. Töte oder verlangsame sie, BEVOR sie ankommen — jeder, der hineinkommt, wird zum Berserker und trifft die ganze Gruppe alle 3 Sekunden. Zieh den Boss zur größten Gruppe; Fernkämpfer übernehmen die Nachzügler.|n• Strudel ziehen durch den Raum, mit einer Lücke dazwischen — stellt euch alle in die Lücke.|n• Erreicht ein Strudel die Blase, platzt sie: Schaden auf alle plus Rückstoß. Steh so, dass du nicht ins Wasser fliegst — dort sind Haie.|n• {SPELL:1313393}: Trifft es dich, hinterlässt du Frostkugeln, wo du läufst. Leg sie zusammen, weg von der Blase und den Laufwegen. Auf Normal nicht berühren (stapelnder Schaden und glattes Eis); auf Heroisch und Mythisch müssen sie aufgenommen werden, sonst zerbersten sie auf die ganze Gruppe.|n• {SPELL:1260837} sind vier Sekunden Schaden auf alle — ein Heil-Cooldown. Auf Heroisch und Mythisch lässt jeder davon sie härter zuschlagen: der langsame Soft Enrage.|n• Nach 10 Minuten kommt der harte Enrage: Dann ist der Pull vorbei.|n• Kampfrausch beim Pull.|n• Aus den Live-Guides und dem aktuellen DBM-Modul, von uns noch nicht selbst gespielt — erzähl uns, was du gesehen hast.",
	RAID_BOSS_NYMRISSA_TANK = "• Normal und Heroisch: {SPELL:1282937} sind mehrere Sekunden harter Treffer auf dich — nutze eine Verteidigung. Nichts zu zielen.|n• Mythisch: {SPELL:1268562} ist eine Linie, die dich zurückstößt und stapelt; richte sie von der Gruppe weg (durch die Eisflächen, sie spült sie weg) und wechsle bei den Stapeln mit dem anderen Tank.|n• Halte sie bei der größten Murlocgruppe, nie direkt auf der Blase.",
	RAID_BOSS_NYMRISSA_HEALER = "• Plane Cooldowns für {SPELL:1260837} (vier Sekunden auf alle) und für das Platzen der Blase. Beides ist vorhersehbar.|n• Ein Murloc-Berserker trifft die ganze Gruppe alle 3 Sekunden, bis er stirbt — ein verpasster Murloc ist, wo die Heilung zerbricht.",
	RAID_BOSS_NYMRISSA_DPS = "• Immer zuerst die Murlocs: töte oder verlangsame sie, bevor sie die Blase erreichen; Betäubungen, Wurzeln und Rückstöße wirken. Ein Berserker stirbt sofort.|n• Mythisch: zuerst den Frostscale — er lässt die Murlocs um ihn herum 99 % weniger Schaden nehmen.|n• Dann zurück auf den Boss.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker: der Boss aus Phase 2 von Daggerspine Point (Beast From the Deep). Lady Selen'vjar lädt ihn mit gestohlener Void-Magie auf.|n• {SPELL:1282587}: 4 Sekunden lang schadet er einem Spieler und allen im Umkreis von 6 Metern um ihn. Steh nicht neben diesem Spieler.|n• {SPELL:1282589}: Er ruft Visions of Madness und hinterlässt Zonen, die jede Sekunde schaden. Geh heraus.|n• {SPELL:1282588}: Seine Verbündeten im Umkreis von 20 Metern nehmen 10 Sekunden lang 25 % weniger Schaden. Kannst du Magie reinigen (Purge), nimm es weg.|n• {SPELL:1282593}: ein Fluch, der deine Angriffe und Zauber eine Minute lang 20 % langsamer macht. Entferne ihn, wenn du kannst.|n• Nur mit der Malevolent-Boons-Challenge: Ein Dark Obelisk in der Nähe gibt ihm 15 % mehr Gesundheit und Schaden plus {SPELL:1284125}, {SPELL:1284085} oder {SPELL:1284064}. Seine Leeren-Spiegel kommen oft zu dritt: Unterbrich jeden einmal, und er verschwindet. Zerstöre zuerst die Obelisken, dann kommt nichts davon.|n• Ein Spieler auf Wowhead: Lauf immer wieder über die Heilkugeln.|n• Aus der Zauberliste von Wowhead, von uns noch nicht selbst gespielt. Erzähl uns, was du gesehen hast.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar: Anführerin der Naga und Endboss von Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Phasen: 1) Ritual Roles: Ihre Captains bewachen das Ritual und entziehen Void-Essenz. 2) Beast From the Deep: Sie verstärkt einen Mindbreaker. 3) Summoner's Fall: Sie kämpft selbst gegen dich.|n• {SPELL:1280255}: Ein Spieler bekommt eine Targeted!-Markierung, dann wirft sie dort einen Dreizack hin. Er trifft alle im Umkreis von 8 Metern und schockt eine Minute lang alle in seiner Nähe. Bist du markiert, geh an den Rand, damit der Dreizack abseits vom Kampf landet.|n• {SPELL:1282365}: 8 Sekunden lang zieht jeder Dreizack auf dem Boden Spieler heran und schadet ihnen. Geh weg von den Dreizacken.|n• {SPELL:1272067} springt auf bis zu 3 Spieler über. In einer Gruppe: Verteilt euch.|n• {SPELL:1281803}: Sie schirmt sich ab. Bricht der Schild, erscheint ein Water Torrent.|n• Spieler auf Wowhead nennen sie viel leichter als Faithbreaker Ger'lok.|n• Aus der Zauberliste von Wowhead, von uns noch nicht selbst gespielt. Erzähl uns, was du gesehen hast.",
	RITUAL_ALERT_BINDING_NEBULA = "Binding Nebula! -> Nebula zerstören",
	RITUAL_ALERT_SHADOWBOLT = "Shadowbolt Volley unterbrechen!",
	RITUAL_ALERT_DISSONANT = "Dissonant Realities unterbrechen!",

	-- Challenges -----------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• Greifende Tendrils erscheinen mit einem wirbelnden grünen Kreis — geh raus, sonst wirst du festgewurzelt und nimmst Schaden.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Loote am Ende einer Stätte eine Ritual Chest und gib dann die Quest \"Ritual Site Challenge Report: Tendrils\" ab.",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Geister erscheinen und beginnen einen langen Zauber. Stoppst du den Zauber, verschwindet der Geist: Ein Kick wirkt, und auch Betäubungen, Furcht und andere Kontrolleffekte. Lässt du ihn fertig wirken, trifft dich seine zehrende Magie.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Schließe eine Tier-3-Stätte ab und sprich dann mit Ranger Captain Lilatha in Silbermond (die nötige Stufe sinkt jede Woche).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Kills rufen Verstärkung herbei; je größer und stärker der getötete Pull, desto stärker die Adds.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Schließe eine Tier-4-Stätte ab und sprich dann mit Lady Darkglen in Silbermond (die nötige Stufe sinkt jede Woche).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Dark Obelisks stärken Gegner in der Nähe — zerstöre die Obelisken, um die Buffs zu entfernen.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Schließe eine Tier-2-Stätte ab für eine Quest von Lady Darkglen und untersuche dann 5 Dark Obelisks in einer Stätte (die nötige Stufe sinkt jede Woche).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Getötete Gegner hinterlassen eine Lache tödlicher Leerenmagie — raus aus der Fläche.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Loote einen Tainted Bone Pile in einer Stätte ab Tier 2 (Standort: siehe Notizen zur Stätte) und gib die Quest ab.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Zusätzliche Gegner in der ganzen Stätte — rechne mit dichteren Packs.|n• Erhöht die Spoils, solange aktiv (einer der größeren Boni).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Schließe eine Tier-2-Stätte ab und sprich dann mit Ranger Captain Lilatha in Silbermond (die nötige Stufe sinkt jede Woche).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Elitegegner patrouillieren durch die Stätte — weich ihren Routen aus, wo es geht.|n• Erhöht die Spoils, solange aktiv.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procure\" einzigartige Schätze aus einer Stätte ab Tier 3 (die nötige Stufe sinkt jede Woche).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Zufällige Gegner UND der Endboss sind verstärkt, markiert durch eine schwebende Kugel über ihnen.|n• Erhöht die Spoils, solange aktiv (einer der größeren Boni).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Loote ein Ember of Power in einer Tier-4-Stätte, um die Quest zu starten (die nötige Stufe sinkt jede Woche).",
})

merge(ns._mhLocales and ns._mhLocales.frFR, {
	-- Titres de section ----------------------------------------------------------
	RITUAL_COACH_SEC_OVERVIEW = "Aperçu",
