	RITUAL_COACH_SEC_SCORING = "Spoils & morts",
	RITUAL_COACH_SEC_WEEKLY = "Hebdo & renommée",
	RITUAL_COACH_SEC_ORBS = "Regeneration Orbs",

	-- Noms affichés (noms propres en anglais) -------------------------------------
	RITUAL_COACH_INTRO_NAME = "Comment fonctionnent les Ritual Sites",
	RITUAL_COACH_SITE_DAGGERSPINE = "Daggerspine Point",
	RITUAL_COACH_SITE_BROKENTHRONE = "Broken Throne",
	RITUAL_CHAL_TENDRILS = "Tendrils",
	RITUAL_CHAL_MANIFESTATIONS = "Manifestations",
	RITUAL_CHAL_ALARMBELLS = "Magical Alarm Bells",
	RITUAL_CHAL_MALEVOLENTBOONS = "Malevolent Boons",
	RITUAL_CHAL_TAINTEDCORPSES = "Tainted Corpses",
	RITUAL_CHAL_REINFORCED = "Reinforced",
	RITUAL_CHAL_PATROLS = "Patrols",
	RITUAL_CHAL_EMBERS = "Embers",

	-- Labels UI du Coach (phase 2) ------------------------------------------------
	RITUAL_COACH_HEADER = "Ritual Coach",
	RITUAL_COACH_CHALLENGES_HEADER = "Challenges — à choisir à partir du Tier 3 (plus hauts Spoils d'abord)",
	RITUAL_COACH_ACTIVE_FMT = "Site de la semaine : %s",
	RITUAL_COACH_ACTIVE_UNKNOWN = "Site actif pas encore détecté — conseils généraux ci-dessous.",
	RITUAL_COACH_STATUS_UNLOCKED = "débloqué",
	RITUAL_COACH_STATUS_LOCKED = "verrouillé",

	-- Partage (phase 3)
	RITUAL_COACH_SHARE_BTN = "Partager les astuces de challenge au groupe",
	RITUAL_SHARE_CHALLENGES_HEADER = "Challenges rituels triés par Spoils :",
	RITUAL_SHARE_XLOC_HEADER_FMT = "%s a partagé des astuces de challenges rituels :",
	RITUAL_SHARE_CONFIRM_FMT = "Poster %d lignes d'astuces de challenges rituels dans ton groupe ?",
	RITUAL_SHARE_SENT_FMT = "%d ligne(s) partagée(s) sur %s.",
	RITUAL_SHARE_SENT_TEST_FMT = "%d ligne(s) partagée(s) (mode test).",
	RITUAL_SHARE_NO_GROUP = "Rejoins un groupe ou un raid pour partager ces astuces (ou active le mode test de partage).",
	RITUAL_SHARE_COMBAT = "Impossible de partager en combat.",
	RITUAL_SHARE_COOLDOWN = "Le partage est en recharge — réessaie dans un instant.",
	RITUAL_SHARE_BUSY = "Un partage est déjà en cours.",
	RITUAL_SHARE_FAILED = "Impossible de construire les astuces de challenge.",

	-- Indice hebdo (pourquoi l'hebdo rituelle n'est pas faite)
	RITUAL_WEEKLY_HINT_LOCKED_FMT = "Verrouillé : %s",
	RITUAL_WEEKLY_HINT_LOCKED_GENERIC = "Verrouillé — débloque les Ritual Sites via la chaîne de quêtes d'introduction à Lune-d'argent.",
	RITUAL_WEEKLY_HINT_PICKUP = "Pas encore prise — cette hebdo vient de Lady Liadrin à Lune-d'argent, et seulement les semaines où elle la propose parmi ses quatre choix.",
	RITUAL_WEEKLY_HINT_INTRO = "Ce personnage n'a pas encore terminé la chaîne de quêtes d'introduction — commence \"Ranger Captain's Summons\" auprès de Ranger Captain Lilatha à Lune-d'argent (l'étape Void Strike se fait dans la zone d'assaut active).",
	RITUAL_INTRO_STEP_FMT = "Chaîne d'introduction sur ce personnage — étape %d/%d : %s",
	RITUAL_INTRO_STEP_INLOG = "(déjà dans votre journal de quêtes)",
	RITUAL_INTRO_STEP_SUMMONS = "commencez \"Ranger Captain's Summons\" auprès de Ranger Captain Lilatha, au camp au-dessus du Bazar.",
	RITUAL_INTRO_STEP_ALLIES = "faites \"Outfitting and Allies\" — rencontrez les alliés au camp de Lilatha.",
	RITUAL_INTRO_STEP_VOIDSTRIKE = "\"Void Strike\" — cette étape se déroule dans la zone d'assaut active (voir Void Assaults ci-dessous).",
	RITUAL_INTRO_STEP_PROBLEMS = "\"Ritual Problems\" — examinez les rapports des sites rituels puis perturbez un site rituel.",
	RITUAL_INTRO_STEP_INTEREST = "\"Ritual Interest\" — faites votre rapport à Lady Darkglen au camp.",
	RITUAL_WEEKLY_HINT_INPROGRESS = "Elle est dans ton journal de quêtes — termine-la et rends-la.",

	-- Intro / comment ça marche -----------------------------------------------------
	RITUAL_TIP_INTRO_TIERS = "• Choisis ton palier au Curious Obelisk ; termine chaque palier pour débloquer le suivant.|n• L'obélisque indique ce que chaque palier demande : le Tier 3 demande 1 challenge actif, le Tier 4 en demande 2, le Tier 5 en demande 4, le Tier 6 en demande 6.|n• Les paliers plus élevés donnent plus de Spoils et de renommée. Niveau d'objet recommandé par le jeu, relevé sur l'obélisque même le 20 août : |cffffffffT1 215 · T2 231 · T3 244 · T4 259 · T5 268 · T6 275|r. Survole un palier dans le menu pour le vérifier toi-même — ces chiffres bougent d'une saison à l'autre.",
	RITUAL_TIP_INTRO_SCORING = "• Les Spoils sont ton score ; la Ritual Chest à la fin s'ajuste dessus.|n• Morts : les 2 premières sont gratuites, ensuite chaque mort retire 5% de Spoils, jusqu'à -50% maximum.|n• Des clears propres valent mieux que des pulls rapides — mourir coûte directement des récompenses.",
	RITUAL_TIP_INTRO_WEEKLY = "• Au lancement, le palier requis pour DÉBLOQUER un challenge baissait d'un cran chaque semaine. Cela dure depuis des mois, donc un palier bas suffit très probablement aujourd'hui.|n• Compte pour la ligne Monde du Great Vault, comme un Delve du même palier.|n• Boosters de renommée : Ritual Tablet (premier site de la semaine), Ritual Tablet Fragment (deuxième site) et Ritual Site Reports (selon tes Spoils).",
	RITUAL_TIP_INTRO_ORBS = "• En combat, des Regeneration Orbs apparaissent et soignent 15% de ta vie (renommée 1).|n• Orb Potency (renommée 4) augmente ce soin.|n• Appuie-toi sur les orbes plutôt que de brûler tes cooldowns en soins personnels.",

	-- Daggerspine Point (Eversong Woods) ----------------------------------------------
	RITUAL_TIP_DAGGERSPINE_OVERVIEW = "• Eversong Woods — Daggerspine Point, sur la côte ouest près de Goldenmist Village.|n• Ennemis : nagas.|n• Actif une semaine à la fois ; l'obélisque affiche une icône violette sur la carte.|n• Entre au Curious Obelisk et choisis-y ton palier + tes challenges.",
	RITUAL_TIP_DAGGERSPINE_PHASES = "• Un court scénario instancié en trois étapes : tue les élites nommés autour du site, puis le Void-Infused Mindbreaker, puis Lady Selen'vjar elle-même.|n• Scénario vu à l'obélisque : “A Strike From the Sea”.|n• Après le kill, loote la Ritual Chest de Lady Selen'vjar, puis sors par l'Obelisk Portal derrière le bâtiment.",
	RITUAL_TIP_DAGGERSPINE_NOTES = "• Tainted Bone Pile (débloque le challenge Tainted Corpses) : /way 66.09 62.58.|n• Dark Obelisks (quête Malevolent Boons — examines-en 5 sur 9) : 66.6/38.8 · 64.7/49.8 · 63.8/70.9 · 39.2/76.2 · 35.3/63.2 · 50/42 · 42/56 · 62/62 · 44.8/47.3.|n• De petits trésors et des Regeneration Orbs sont dispersés sur le site.",

	-- Broken Throne (Zul'Aman) -----------------------------------------------------
	RITUAL_TIP_BROKENTHRONE_OVERVIEW = "• Zul'Aman — Broken Throne, au sud de la zone.|n• Ennemis : cultistes de la Twilight's Blade.|n• Actif une semaine à la fois ; l'obélisque affiche une icône violette sur la carte.|n• Entre au Curious Obelisk et choisis-y ton palier + tes challenges.",
	RITUAL_TIP_BROKENTHRONE_PHASES = "• Un court scénario instancié en trois étapes : tue les ennemis nommés autour du site, puis le Corrupted Amani Dragonhawk, puis Faithbreaker Ger'lok dans le bâtiment.|n• Scénario vu à l'obélisque : “A Corrupted Path”.|n• Corrupted Amani Dragonhawk : mets-toi dans les petites flaques rouges (Volatile Plumage) pour qu'elles n'éclatent pas sur tout le groupe, et ne reste jamais face à son Shadowflame Breath.|n• Seulement avec le challenge Malevolent Boons : les Dark Obelisks donnent des sorts en plus aux ennemis, comme une Binding Nebula qui te piège jusqu'à ce que tu la tues, et des miroirs du Vide dont tu dois interrompre l'incantation. Détruis d'abord les obélisques et rien de tout ça ne vient.|n• Ensuite, loote la Ritual Chest de Faithbreaker Ger'lok.",
	RITUAL_TIP_BROKENTHRONE_NOTES = "• Tainted Bone Pile (débloque le challenge Tainted Corpses) : /way 47.91 36.52.|n• Dark Obelisks (quête Malevolent Boons — examines-en 5 au choix ; 9 apparitions) : 61/50 · 41/50 · 45/59 · 42/68 · 55/58 · 54/54 · 50/57 · 45/64 · 47/76.|n• Détruire les Dark Obelisks retire les buffs qui renforcent les ennemis du site — les éliminer rend les boss nettement plus faciles (ne les laisse debout que si tu vises le haut fait sans obélisque).|n• De petits trésors et des Regeneration Orbs sont dispersés sur le site.",
	RITUAL_BOSS_DRAGONHAWK_STEPS = "• {SPELL:1291559} laisse de petites FLAQUES ROUGES. Mets-toi dans une flaque pour la soak : tu ne prends qu'un petit coup. Une flaque où personne ne se tient explose pour d'énormes dégâts de Shadowflame et peut tuer tout le groupe. Un joueur par flaque suffit.|n• Reste DERRIÈRE le faucon-dragon. Son {SPELL:1291519} frontal est mortel et continue de brûler après le coup.|n• {SPELL:1291733} : il entre en enrage et attaque plus vite pendant 15 secondes. Si ta classe peut retirer un Enrage, fais-le maintenant.|n• Seulement avec le challenge Malevolent Boons : un Dark Obelisk proche lui donne 15 % de vie et de dégâts en plus et un sort supplémentaire. Détruis les obélisques avant le combat et aucun des trois ci-dessous ne vient.|n• {SPELL:1284125} : une nébuleuse piège un joueur au hasard. Elle fait mal chaque seconde et te ralentit de 40 %. Tu ne peux pas en sortir à pied tant qu'elle vit, alors tue la nébuleuse.|n• {SPELL:1284085} : des miroirs du Vide apparaissent et incantent {SPELL:1284083}, une incantation de 12 secondes qui touche tout le monde dans un rayon de 100 mètres. Impossible de la fuir. Interromps-la une fois et le miroir disparaît.|n• {SPELL:1284064} : des vagues de Vide qui font vite mal et te repoussent.",
	RITUAL_BOSS_DRAGONHAWK_QUICK = "Flaques rouges : Mets-toi dans une flaque rouge pour qu'elle n'explose pas sur tout le monde.|nSouffle : Reste derrière le faucon-dragon, son souffle devant lui est mortel.|nObélisques : Avec Malevolent Boons actif, détruis d'abord les Dark Obelisks, il n'aura alors pas de sorts en plus.",
	RITUAL_BOSS_GERLOK_STEPS = "• Il appelle des aides et les renforce avec {SPELL:1277776} : ils frappent plus fort et ne peuvent pas être étourdis, ralentis ni immobilisés. Pendant ce temps, il subit 90 % de dégâts en moins ({SPELL:1279189}). Tue les aides dès qu'ils arrivent.|n• {SPELL:1278896} : du feu tombe au sol et continue de brûler. Sors-en tout de suite, il te tue presque d'un coup.|n• {SPELL:1277559} est LA incantation à interrompre : un gros coup sur tout le monde dans un rayon de 50 mètres, et les piliers ne la bloquent pas. Toutes ses incantations ne sont pas interruptibles, alors garde ton kick pour celle-là.|n• {SPELL:1279288} est spammé sur un joueur. Coupe la ligne de vue derrière les piliers.|n• Garde-le SUR sa plateforme. Le tirer en bas ou hors de celle-ci réinitialise le combat (Rob, en jeu). L'espace est étroit, mais ne cherche pas de place en contrebas.|n• Challenge Embers : chaque Ember encore allumée le rend beaucoup plus fort. Un joueur sur Wowhead a vu environ 60 % de vie et de dégâts en plus avec les quatre actives. Tue les monstres marqués autour de chaque Ember avant le boss pour l'éteindre.",
	RITUAL_BOSS_GERLOK_QUICK = "Adds : Tue ses aides tout de suite, car tant qu'ils vivent, il ne prend presque pas de dégâts.|nInterrompre : Garde ton sort d'interruption pour Shadowbolt Volley, son gros coup sur tout le monde.|nPiliers : Cache-toi derrière un pilier pour que son Shadow Blast ne puisse pas te toucher.",
	RITUAL_BOSS_MINDBREAKER_QUICK = "Obélisques : Avec Malevolent Boons actif, détruis d'abord les Dark Obelisks, il n'aura alors pas de sorts en plus.|nMiroirs : Si des miroirs du Vide apparaissent, interromps chacun une fois et il disparaît.|nOrbes : Passe sans arrêt sur les orbes de soin.",
	RITUAL_BOSS_SELENVJAR_QUICK = "Trident : Si tu es marqué, va au bord pour que le trident tombe loin du combat.|nAttraction : Quand les tridents t'attirent, éloigne-toi d'eux.|nÉclair : En groupe, écartez-vous pour que sa Chain Lightning touche moins de joueurs.",
	RAID_BOSS_ROTMIRE_STEPS = "• Un seul boss et une boucle qui se répète jusqu'à sa mort. Furie sanguinaire au pull. Chaque {SPELL:1221787} ajoute un cumul de Rotting Pustules qui reste, donc les dégâts sur le raid montent sans cesse : plus le combat dure, plus il est dur.|n• {SPELL:1221622} : des cercles au sol montrent où les adds apparaissent. Sors-en, sinon tu es projeté au loin et tu prends très cher. Chaque add (Shroomling) poursuit un joueur : amène-le dans un seul tas serré près du boss, pour que le raid les tue tous ensemble.|n• Tue tous les adds avant que sa barre d'énergie soit pleine. À 100 d'énergie, il lance {SPELL:1221637} : un coup sur tout le monde, une projection et un DoT de 16 secondes. Un add encore en vie reçoit alors Fungal Frenzy : vie pleine, et il ne peut plus être étourdi ni interrompu.|n• Après {SPELL:1221637}, chaque cadavre d'add devient un Bursting Shroom. Tue-les tous en 16 secondes environ : chacun qui reste explose sur tout le raid, et plus d'une explosion vous fait presque toujours wipe. C'est pour ça que les adds meurent en un seul tas.|n• {SPELL:1222088} ralentit quelques joueurs et les blesse. Va au bord de la salle avant la fin : il laisse une zone ({SPELL:1222129}) qui reste. Garde le centre et le tas d'adds dégagés, et sors de toute zone.|n• En Héroïque et Mythique : un add Sporecap apparaît aussi et ne bouge pas. Interromps son Poison Burst à chaque fois, sinon tout le raid cumule un DoT. Amène les autres adds vers lui et tue-les là.|n• En Mythique : des Funglings arrivent aussi. Un cadavre de Shroomling à moins de 10 mètres d'un cadavre de Fungling crée un Bursting Doom Shroom, et ça fait wipe le raid. Tue les deux types à deux endroits séparés.",
	RAID_BOSS_ROTMIRE_QUICK_DPS = "Tue tous les adds du tas avant que sa barre soit pleine, puis tue les champignons tout de suite.",
	RAID_BOSS_ROTMIRE_QUICK_HEALER = "Les dégâts grossissent à chaque boucle, alors garde tes cooldowns pour le gros coup quand sa barre est pleine.",
	RAID_BOSS_ROTMIRE_QUICK_TANK = "Alterne avec l'autre tank après chaque gros coup, et garde le boss près du tas d'adds.",
	RAID_BOSS_ROTMIRE_QUICK = "Adds : Amène les petits adds champignons en un seul tas et tue-les avant que sa barre d'énergie soit pleine.|nChampignons : Quand sa barre est pleine, les adds morts deviennent des champignons, alors tue-les vite avant qu'ils explosent.|nLianes : Si des lianes te ralentissent, va au bord de la salle pour que la flaque qu'elles laissent ne gêne personne.",
	RAID_BOSS_ROTMIRE_TANK = "• Alterne avec l'autre tank après chaque {SPELL:1221781} : il te projette en l'air et te fait subir plus de dégâts physiques pendant 14 secondes (35 % en Normal, 75 % en Héroïque et Mythique). Utilise une défensive pour le coup.|n• Garde le boss à côté du tas d'adds, pour que le raid le frappe pendant qu'il tue les adds. En Héroïque et Mythique : amène-le au Sporecap.",
	RAID_BOSS_ROTMIRE_HEALER = "• Les dégâts sur le raid montent pendant tout le combat : chaque {SPELL:1221787} ajoute un cumul de Rotting Pustules, donc chaque boucle est plus dure que la précédente.|n• Prévois des cooldowns de raid pour {SPELL:1221637} (un coup plus un DoT de 16 secondes sur tout le monde) et pour chaque Bursting Shroom qui explose.|n• Le tank touché par {SPELL:1221781} subit beaucoup plus de dégâts physiques pendant 14 secondes.",
	RAID_BOSS_ROTMIRE_DPS = "• Cleave les adds dans leur tas, et fais en sorte qu'ils soient tous morts avant {SPELL:1221637}. Ensuite, passe tout de suite sur les Bursting Shrooms.|n• En Héroïque et Mythique : interromps le Poison Burst du Sporecap à chaque fois.|n• En Mythique : les Shroomlings et les Funglings meurent à deux endroits séparés, à au moins 10 mètres l'un de l'autre.",
	RAID_BOSS_NYMRISSA_STEPS = "• |cffffd100L’entrée est SOUS L’EAU|r — une grotte immergée, votre jauge de respiration tourne donc avant même le combat. Des bulles d’air près de l’entrée la remplissent.|n• Un seul boss, une boucle qui se répète jusqu’à sa mort. Compte pour la ligne Raid de votre Great Vault.|n• |cffffd100Les murlocs sont le combat.|r {SPELL:1257717} place une grande bulle au centre et les murlocs courent vers elle. Tuez-les ou ralentissez-les AVANT qu’ils l’atteignent — chacun qui entre devient un Berserker qui frappe tout le groupe toutes les 3 secondes. Amenez le boss vers le plus gros paquet ; les distances prennent les isolés.|n• Des tourbillons encerclent la salle avec un seul passage libre — regroupez-vous dans ce passage.|n• Quand un tourbillon atteint la bulle, elle éclate : dégâts sur tout le monde et projection. Placez-vous pour ne pas être projeté dans l’eau — il y a des requins.|n• {SPELL:1313393} : si vous êtes touché, vous laissez des orbes de givre là où vous marchez. Regroupez-les, loin de la bulle et des passages. En Normal, n’y touchez pas (dégâts cumulés et glace glissante) ; en Héroïque et Mythique il faut les ramasser, sinon elles volent en éclats sur tout le groupe.|n• {SPELL:1260837}, ce sont quatre secondes de dégâts sur tout le monde — un cooldown de soin. En Héroïque et Mythique, chacune la rend plus forte : l’enrage lent.|n• Après 10 minutes arrive l’enrage final : le pull est terminé.|n• Furie sanguinaire au pull.|n• D’après les guides en jeu et le module DBM actuel, pas encore testé par nous — dites-nous ce que vous avez vu.",
	RAID_BOSS_NYMRISSA_TANK = "• Normal et Héroïque : {SPELL:1282937}, ce sont plusieurs secondes de gros coups sur vous — utilisez une défensive. Rien à orienter.|n• Mythique : {SPELL:1268562} est une ligne qui vous repousse et se cumule ; orientez-la loin du groupe (à travers les plaques de glace, elle les efface) et changez de tank sur les cumuls.|n• Gardez-la près du plus gros paquet de murlocs, jamais sur la bulle.",
	RAID_BOSS_NYMRISSA_HEALER = "• Prévoyez des cooldowns pour {SPELL:1260837} (quatre secondes sur tout le monde) et pour l’éclatement de la bulle. Les deux sont prévisibles.|n• Un Berserker murloc frappe tout le groupe toutes les 3 secondes tant qu’il vit — un murloc raté, c’est là que les soins lâchent.",
	RAID_BOSS_NYMRISSA_DPS = "• Toujours les murlocs d’abord : tuez-les ou ralentissez-les avant la bulle ; étourdissements, immobilisations et projections fonctionnent. Un Berserker meurt tout de suite.|n• Mythique : tuez d’abord le Frostscale — il réduit de 99 % les dégâts subis par les murlocs autour de lui.|n• Puis retour sur le boss.",
	RITUAL_BOSS_MINDBREAKER_STEPS = "• Void-Infused Mindbreaker : le boss de la phase 2 de Daggerspine Point (Beast From the Deep). Lady Selen'vjar le charge de magie du Vide volée.|n• {SPELL:1282587} : pendant 4 secondes, il blesse un joueur et tout le monde à 6 mètres de lui. Ne reste pas à côté de ce joueur.|n• {SPELL:1282589} : il appelle des Visions of Madness et laisse des zones qui font mal chaque seconde. Sors-en.|n• {SPELL:1282588} : ses alliés dans un rayon de 20 mètres subissent 25 % de dégâts en moins pendant 10 secondes. Si tu peux purger la Magie, retire-le.|n• {SPELL:1282593} : une Malédiction qui rend tes attaques et tes incantations 20 % plus lentes pendant une minute. Retire-la si tu peux.|n• Seulement avec le challenge Malevolent Boons : un Dark Obelisk proche lui donne 15 % de vie et de dégâts en plus, plus {SPELL:1284125}, {SPELL:1284085} ou {SPELL:1284064}. Ses miroirs du Vide arrivent souvent par trois : interromps chacun une fois et il disparaît. Détruis d'abord les obélisques et rien de tout ça ne vient.|n• Un joueur sur Wowhead : passe sans arrêt sur les orbes de soin.|n• D'après la liste de sorts de Wowhead, pas encore fait par nous. Dis-nous ce que tu as vu.",
	RITUAL_BOSS_SELENVJAR_STEPS = "• Lady Selen'vjar : cheffe naga et boss final de Daggerspine Point (Eversong Woods, /way 34.9 65.4).|n• Phases : 1) Ritual Roles : ses capitaines gardent le rituel et drainent l'essence du Vide. 2) Beast From the Deep : elle renforce un Mindbreaker. 3) Summoner's Fall : elle t'affronte elle-même.|n• {SPELL:1280255} : un joueur reçoit une marque Targeted!, puis elle lance un trident à cet endroit. Il touche tout le monde dans un rayon de 8 mètres et électrocute tous ceux qui sont proches pendant une minute. Si tu es marqué, va au bord pour que le trident tombe loin du combat.|n• {SPELL:1282365} : pendant 8 secondes, chaque trident au sol attire les joueurs et les blesse. Éloigne-toi des tridents.|n• {SPELL:1272067} rebondit sur jusqu'à 3 joueurs. En groupe, écartez-vous.|n• {SPELL:1281803} : elle se protège avec un bouclier. Quand le bouclier se brise, un Water Torrent apparaît.|n• Les joueurs sur Wowhead la trouvent bien plus facile que Faithbreaker Ger'lok.|n• D'après la liste de sorts de Wowhead, pas encore fait par nous. Dis-nous ce que tu as vu.",
	RITUAL_ALERT_BINDING_NEBULA = "Binding Nebula ! -> détruisez la nébuleuse",
	RITUAL_ALERT_SHADOWBOLT = "Interrompez Shadowbolt Volley !",
	RITUAL_ALERT_DISSONANT = "Interrompez Dissonant Realities !",

	-- Challenges ---------------------------------------------------------------------
	RITUAL_TIP_TENDRILS_MECHANIC = "• Des tendrils apparaissent avec un cercle vert tourbillonnant — sors-en, sinon tu es immobilisé et tu prends des dégâts.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_TENDRILS_UNLOCK = "• Loote une Ritual Chest à la fin d'un site, puis rends la quête \"Ritual Site Challenge Report: Tendrils\".",
	RITUAL_TIP_MANIFESTATIONS_MECHANIC = "• Des esprits apparaissent et commencent une longue incantation. Arrête l'incantation et l'esprit disparaît : une interruption marche, et aussi les étourdissements, les peurs et les autres contrôles. Laisse-la finir et tu subis sa magie flétrissante.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_MANIFESTATIONS_UNLOCK = "• Termine un site Tier 3, puis parle à Ranger Captain Lilatha à Lune-d'argent (le palier requis baisse chaque semaine).",
	RITUAL_TIP_ALARMBELLS_MECHANIC = "• Les kills invoquent des renforts ; plus le pull tué est gros et fort, plus les adds sont puissants.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_ALARMBELLS_UNLOCK = "• Termine un site Tier 4, puis parle à Lady Darkglen à Lune-d'argent (le palier requis baisse chaque semaine).",
	RITUAL_TIP_MALEVOLENTBOONS_MECHANIC = "• Des Dark Obelisks renforcent les ennemis proches — détruis les obélisques pour retirer les buffs.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_MALEVOLENTBOONS_UNLOCK = "• Termine un site Tier 2 pour une quête de Lady Darkglen, puis examine 5 Dark Obelisks dans un site (le palier requis baisse chaque semaine).",
	RITUAL_TIP_TAINTEDCORPSES_MECHANIC = "• Les ennemis tués laissent une flaque de magie du Vide mortelle — sors-en.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_TAINTEDCORPSES_UNLOCK = "• Loote un Tainted Bone Pile dans un site Tier 2+ (voir les notes du site pour l'emplacement), puis rends la quête.",
	RITUAL_TIP_REINFORCED_MECHANIC = "• Des ennemis supplémentaires sont répartis sur tout le site — attends-toi à des packs plus denses.|n• Augmente les Spoils tant qu'actif (un des plus gros bonus).",
	RITUAL_TIP_REINFORCED_UNLOCK = "• Termine un site Tier 2, puis parle à Ranger Captain Lilatha à Lune-d'argent (le palier requis baisse chaque semaine).",
	RITUAL_TIP_PATROLS_MECHANIC = "• Des ennemis d'élite patrouillent sur le site — évite leurs trajets quand c'est possible.|n• Augmente les Spoils tant qu'actif.",
	RITUAL_TIP_PATROLS_UNLOCK = "• \"Procure\" des trésors uniques dans un site Tier 3+ (le palier requis baisse chaque semaine).",
	RITUAL_TIP_EMBERS_MECHANIC = "• Des ennemis aléatoires ET le boss final sont renforcés, marqués d'un orbe flottant au-dessus d'eux.|n• Augmente les Spoils tant qu'actif (un des plus gros bonus).",
	RITUAL_TIP_EMBERS_UNLOCK = "• Loote un Ember of Power dans un site Tier 4 pour lancer la quête (le palier requis baisse chaque semaine).",
})

merge(ns._mhLocales and ns._mhLocales.esES, {
	-- Títulos de sección ---------------------------------------------------------
	RITUAL_COACH_SEC_OVERVIEW = "Resumen",
