	-- Rótulos de UI do Coach (fase 2) -------------------------------------------------
	RITUAL_COACH_HEADER = "Ritual Coach",
	RITUAL_COACH_CHALLENGES_HEADER = "Challenges — escolha a partir do Tier 3 (maior Spoils primeiro)",
	RITUAL_COACH_ACTIVE_FMT = "Local desta semana: %s",
